// ============================================================
// LOCAL STORAGE
// ============================================================

function loadCards() {

    try {

        const stored =
            localStorage.getItem(
                "walletCards"
            );


        if (!stored) {

            return [
                ...DEFAULT_CARDS
            ];

        }


        const parsed =
            JSON.parse(stored);


        if (!Array.isArray(parsed)) {

            return [
                ...DEFAULT_CARDS
            ];

        }


        return parsed;

    } catch (error) {

        console.error(
            "Errore caricamento tessere:",
            error
        );


        return [
            ...DEFAULT_CARDS
        ];

    }
}
